import arrow
from arrow.parser import ParserMatchError

def test_invalid_hour_with_am_pm(hour_str, am_pm_str, format_str):
    try:
        arrow.get(f"{hour_str} {am_pm_str}", format_str)
        print(f"REPRO FAIL: {hour_str} {am_pm_str} should have raised an error")
    except (ParserMatchError, ValueError) as e:
        print(f"REPRO PASS: Caught expected error for {hour_str} {am_pm_str}: {e}")
    except Exception as e:
        print(f"REPRO FAIL: Caught unexpected exception for {hour_str} {am_pm_str}: {type(e).__name__}: {e}")

# These should fail (raise error)
test_invalid_hour_with_am_pm("13", "AM", "h A")
test_invalid_hour_with_am_pm("13", "PM", "h A")
test_invalid_hour_with_am_pm("0", "AM", "h A")
test_invalid_hour_with_am_pm("0", "PM", "h A")

# These should pass (not raise error)
try:
    arrow.get("12 AM", "h A")
    print("PASS: 12 AM is valid")
except Exception as e:
    print(f"FAIL: 12 AM should be valid: {e}")

